    ["No model installed"] = "Aucun modèle installé",
    ["another model"] = "un autre modèle",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "Le modèle Local AI que vous avez choisi est absent, ne tient pas dans la mémoire graphique libre ou n'a pas pu démarrer ; {model} a donc été utilisé à la place.",
    ["Choose one of the listed Local AI models."] = "Choisissez l’un des modèles Local AI listés.",
    ["Deletes the saved key. The Inworld cloud voice stops until you add a key again."] = "Supprime la clé enregistrée. La voix cloud Inworld s'arrête jusqu'à ce que vous ajoutiez à nouveau une clé.",
    ["Inworld cloud voice"] = "Voix cloud Inworld",
    ["Inworld did not accept that key."] = "Inworld n'a pas accepté cette clé.",
    ["Inworld API key"] = "Clé d’API Inworld",
    ["The Inworld cloud voice speaks only English here. Turn off Multilingual conversations to choose it."] = "La voix cloud Inworld ne parle qu’anglais ici. Désactivez Conversations multilingues pour la choisir.",
    ["{voice} · needs Inworld key"] = "{voice} · nécessite la clé d'API Inworld",
    ["Characters to invite"] = "Personnages à inviter",
    ["Whose memories"] = "Souvenirs de qui",
    ["Invalid Mature content settings."] = "Paramètres de contenu pour adultes non valides.",
    ["Your message was not sent. Open the text box again and retype it."] = "Votre message n'a pas été envoyé. Rouvrez la zone de texte et saisissez-le à nouveau.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Non utilisable : {models}. Voir les notes sur Local AI, « Ajouter votre propre modèle ».",
    ["an embedding model, not a chat model"] = "un modèle d'embedding, pas un modèle de chat",
