    ["{name} (custom)"] = "{name} (personnalisé)",
    ["{name}: {reason}"] = "{name} : {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Préparation de {name} : en attente de la connexion du service de conversation…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Préparation de {name} : en attente du chargement du modèle vocal…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Préparation de {name} : en attente de l'ouverture de la connexion de conversation…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Préparation de {name} : en attente de la mise en place du personnage par le jeu…",
    ["Preparing {name}: waiting for the memory service…"] = "Préparation de {name} : en attente du service de mémoire…",
    ["Preparing {count} more companions…"] = "Préparation de {count} autres compagnons…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "Le service de conversation n'a pas répondu. Patientez un instant, puis invitez à nouveau.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "Le modèle vocal n'a pas été chargé. Vérifiez la voix dans Paramètres ou choisissez-en une autre, puis invitez à nouveau.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Le service de mémoire n'a pas répondu. Vérifiez votre connexion, puis invitez à nouveau.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "La connexion de conversation ne s'est pas ouverte. Vérifiez votre connexion, puis invitez à nouveau.",
    ["Calls are not available during combat."] = "Les appels ne sont pas disponibles pendant un combat.",
    ["Calls are not available right now."] = "Les appels ne sont pas disponibles pour le moment.",
    ["Holocall ended: combat started."] = "Holoappel terminé : le combat a commencé.",
    ["Holocall with {name} ended."] = "Holoappel avec {name} terminé.",
    ["Live holocall picture"] = "Image en direct du holoappel",
    ["Live picture unavailable. The call continues with the portrait."] = "Image en direct indisponible. L'appel continue avec le portrait.",
    ["This contact cannot take a holocall."] = "Ce contact ne peut pas recevoir de holoappel.",
    ["You are already on a call."] = "Vous êtes déjà en appel.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "Un compagnon proche fait un bref commentaire au début d’un combat, puis un autre après.\n\nDélai de dix minutes après un combat. Les conversations et les scènes de l’histoire passent avant. Charger une sauvegarde réinitialise le délai.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Demandez à un compagnon de conduire jusqu’au repère choisi sur la carte.\n\nMontez sur le siège passager quand il est prêt.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Auto : suit la rencontre terminée dans cette sauvegarde.\n\nDécontracté : parle avec cette familiarité.\n\nOrdinaire : garde son comportement habituel.\n\nN’implique pas de relation en cours.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Auto : suit la relation dans cette sauvegarde.\n\nRomantique : parle à V comme à un partenaire.\n\nOrdinaire : garde sa manière habituelle.\n\nModifie seulement leur façon de parler, jamais vos choix dans le jeu.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "L’audio Bluetooth arrive un peu en retard : les lèvres et les sous-titres peuvent devancer la voix. Ceci les retient pour qu’ils suivent, pour toutes les voix.\n\nAuto : 150 ms quand Windows joue via Bluetooth, aucun décalage sinon. Choisissez une valeur si votre casque est plus rapide ou plus lent.\n\nLes dialogues du jeu ont le même retard et ne sont pas corrigés.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate."] = "Ne change que les menus et notifications de ce mod.\n\nLes voix des personnages et la langue de vos échanges sont séparées.",
    ["Characters sometimes ask about something you said, pick up something from earlier or share a thought that invites an answer.\n\nNow and then, never on every reply, and never while you are leaving, giving an order or fighting."] = "Les personnages demandent parfois des précisions sur ce que vous avez dit, reprennent un élément antérieur ou partagent une idée qui appelle une réponse.\n\nDe temps en temps, jamais à chaque réponse, et jamais pendant que vous partez, donnez un ordre ou combattez.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "L’historique du chat reste disponible d’une session à l’autre.\n\nOublier un personnage efface aussi ses messages et brouillons du Chat. Effacer tous les souvenirs efface tous les chats enregistrés.",
    ["Cinematic: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nThe Subtitles switch turns both off."] = "Cinématique : les sous-titres habituels des dialogues du jeu.\n\nAu-dessus du locuteur : au-dessus du compagnon qui parle.\n\nL’interrupteur Sous-titres désactive les deux.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "Les compagnons commentent après que vous avez ramassé du butin dans le monde ; les transferts de stockage restent silencieux.\n\nLes commentaires ordinaires sont espacés de dix minutes ; un équipement légendaire nouvellement obtenu a un délai propre de deux minutes.\n\nLes ramassages pendant un combat sont regroupés en un seul commentaire à la fin.",
    ["Companions gesture while they speak longer replies and nod while you talk, with the game’s own animations in their usual stance.\n\nThey stop at once when anyone moves or a fight starts."] = "Les compagnons gesticulent en donnant des réponses longues et hochent la tête pendant que vous parlez, avec les animations du jeu.\n\nIls s’arrêtent aussitôt quand quelqu’un bouge ou qu’un combat commence.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. Each character decides when; it stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Les compagnons marquent parfois une pause, hésitent, rient ou soupirent, selon leur personnalité. Chaque personnage décide quand ; cela reste rare.\n\nOmniVoice peut faire entendre rires et soupirs ; les autres voix ajoutent seulement des pauses.\n\nNon disponible avec la voix cloud de Convai : la choisir désactive ceci, et activer ceci fait passer la voix sur Pocket.",
    ["Copy your free key from Mistral first (signing up there needs phone verification). It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder. Mistral allows about one message a second and about 5,000 turns a day. It sets its own monthly cap, estimated at about 150,000 turns."] = "Copiez d’abord votre clé gratuite Mistral (l’inscription exige une vérification par téléphone). Elle est lue une fois depuis le presse-papiers, vérifiée auprès de Mistral et enregistrée sur cet ordinateur.\n\nVous pouvez aussi l’enregistrer dans player-mistral-key.txt, dans le dossier du service de conversation. Mistral autorise environ un message par seconde et environ 5 000 tours par jour. Mistral fixe sa propre limite mensuelle, estimée à environ 150 000 tours.",
    ["Copy your key from Inworld first. It is read from the clipboard once, checked with Inworld and saved on this computer.\n\nYou can also save it in player-inworld-key.txt in the conversation service folder. It is used only for the Inworld voice."] = "Copiez d’abord votre clé Inworld. Elle est lue une fois depuis le presse-papiers, vérifiée auprès d’Inworld et enregistrée sur cet ordinateur.\n\nVous pouvez aussi l’enregistrer dans player-inworld-key.txt, dans le dossier du service de conversation. Elle n’est utilisée que pour la voix Inworld.",
    ["Custom models are ones you added; they join the default choice by size."] = "Les modèles personnalisés sont ceux que vous avez ajoutés, classés par taille.",
    ["Each character marks its own feelings as it speaks, so the face changes at that word instead of being guessed from the text. Subtle, set by personality, only where a feeling really shifts.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Chaque personnage marque ses propres émotions en parlant, si bien que le visage change à ce mot au lieu d’être deviné à partir du texte. Subtil, selon la personnalité, seulement quand une émotion change vraiment.\n\nNon disponible avec la voix cloud de Convai : la choisir désactive ceci, et activer ceci fait passer la voix sur Pocket.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Yeux seuls : la tête reste immobile et seuls les yeux bougent.\n\nSubtil à Fort : la tête se tourne de plus en plus vers vous.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups (joining steps, dismissals, driving instructions, results of companion actions), writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nPreparation progress, joined notices, failures and replies to Stop trip stay visible when it is off."] = "Pour les tests et les rapports de bugs ; laissez désactivé pour une partie normale.\n\nAffiche les pop-ups courants (arrivées, renvois, instructions de conduite, résultats des actions des compagnons), écrit une trace de mouvement dans le dossier du mod, journalise les décisions de gestes et s’ajoute aux rapports d’assistance.\n\nLa progression de préparation, les avis d’arrivée, les échecs et les réponses à Arrêter le trajet restent visibles quand il est désactivé.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "Effacer tous les souvenirs s’applique à ces personnages.\n\nParcourir le catalogue ou inviter un compagnon n’ajoute personne à ce décompte.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "Membres de gangs, officiers de la NCPD, gardes, ripperdocs, commerçants, barmans et passants répondent selon leur type de personne.\n\nIls ne connaissent pas votre histoire et vous oublient après le chargement d’une sauvegarde, sauf les commerçants que vous revoyez.\n\nLes personnages nommés ne sont pas concernés.",
    ["Talk to story characters"] = "Parler aux personnages de l’histoire",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand. They use their own voice and memory, and their face follows what they say.\n\nNothing else about them changes: they do not turn, move, gesture or follow. They do not answer during scenes, quest conversations, fights or rides.\n\nTakes effect after you reload your save."] = "Les personnages nommés propres au jeu, comme Judy, Jackie, Panam et Rogue, répondent lorsque vous leur parlez là où ils se trouvent. Ils utilisent leur propre voix et leur mémoire, et leur visage suit ce qu’ils disent.\n\nRien d’autre ne change pour eux : ils ne se retournent pas, ne bougent pas, ne gesticulent pas et ne vous suivent pas. Ils ne répondent pas pendant les scènes, les dialogues de quête, les combats ou les trajets.\n\nCela prend effet après le rechargement de votre sauvegarde.",
    ["{name} is busy right now."] = "{name} est occupé pour l’instant.",
    ["Gets a conversation ready when you look at, approach or have just talked to a character, so they answer without a wait. Paused in combat and scenes.\n\nLimits: two characters ready at once, a new one every 3 s, released after 40 s unused. A crowd never adds up."] = "Prépare une conversation quand vous regardez un personnage, vous approchez de lui ou venez de lui parler, pour qu’il réponde sans attente. Suspendu en combat et pendant les scènes.\n\nLimites : deux personnages prêts à la fois, un nouveau toutes les 3 s, libéré après 40 s sans usage. Une foule ne s’additionne jamais.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Si un personnage cesse de répondre, si les voix s’arrêtent ou si une erreur apparaît : choisissez Générer le rapport et envoyez le fichier indiqué au développeur, avec une courte note sur ce que vous faisiez.\n\nLes journaux listés ci-dessous montrent ce qui a mal tourné.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Les personnages invités sont préparés immédiatement. Leurs souvenirs commencent quand vous leur parlez réellement.\n\nUne identité de joueur unique est partagée entre toutes les sauvegardes et reste la même après un oubli.\n\nLe contexte de jeu actuel décrit le monde que vous avez chargé.",
    ["Inworld · Cloud voice"] = "Inworld · Voix cloud",
    ["Inworld · needs key"] = "Inworld · clé requise",
    ["Needs Local AI."] = "Nécessite Local AI.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Modèles pour adultes uniquement. Activez le Contenu pour adultes.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Jamais autorisé : sexe avec des mineurs ou sans consentement, sexe avec de vraies personnes, haine, instructions réelles d’armes ou de drogues. Un contrôle de sécurité applique la règle sur les mineurs.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Désactivé : texte seul, aucune voix.\n\nAvec les Sous-titres aussi désactivés, les réactions automatiques restent muettes.",
    ["Pocket: the lightest, runs on your CPU, starts speaking in about 0.2 s.\n\nOmniVoice: richer, especially on harder voices. Needs a capable GPU and the OmniVoice pack (greyed out until it is installed); the higher tiers start in 1 to 2.5 s.\n\nVoxtral: each companion’s own voice from the cloud, with your own Mistral key, English only. It loads no local voice model.\n\nConvai: its own cloud voice. A voice that cannot run is replaced by a simpler one, with one notice."] = "Pocket : le plus léger, tourne sur votre processeur et commence à parler en 0,2 s environ.\n\nOmniVoice : plus riche, surtout sur les voix difficiles. Nécessite un GPU performant et le pack OmniVoice (grisé tant qu’il n’est pas installé) ; les niveaux supérieurs démarrent en 1 à 2,5 s.\n\nVoxtral : la voix propre à chaque compagnon, depuis le cloud, avec votre propre clé Mistral, en anglais uniquement. Il ne charge aucun modèle de voix local.\n\nConvai : sa propre voix cloud. Une voix qui ne peut pas tourner est remplacée par une plus simple, avec une seule notification.",
    ["Right after the game’s own dialogue with a character, they know its last few lines, including your chosen replies and your phone calls with them.\n\nOnly the last few minutes count, and none of it is saved to memory."] = "Juste après le dialogue du jeu avec un personnage, celui-ci connaît ses dernières répliques, y compris vos réponses choisies et vos appels téléphoniques avec lui.\n\nSeules les dernières minutes comptent, et rien de tout cela n’est enregistré en mémoire.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Voir les souvenirs de chaque personnage ; en effacer un ou tous.\n\nConservés d’une sauvegarde à l’autre.",
    ["Shows companion replies as text.\n\nWith Voice playback off as well, automatic reactions stay silent."] = "Affiche les réponses en texte.\n\nAvec la Lecture vocale désactivée aussi, les réactions automatiques restent muettes.",
    ["Shows the character live in a holocall instead of their portrait.\n\nIf she cannot be shown, the call goes on with the portrait."] = "Affiche le personnage en direct dans un holoappel au lieu de son portrait.\n\nSi elle ne peut pas être affichée, l’appel continue avec le portrait.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+), Local AI only."] = "Langage fort, violence graphique, drogues et, entre adultes consentants, flirt et sexe. Réservé aux adultes (18+), uniquement avec Local AI.",
    ["Talk in any language; each character answers in yours.\n\nA separate multilingual copy of each character is used, so what they remember from these talks stays apart from your English ones. Forgetting a character clears both.\n\nPocket and Voxtral speak English only, so this switches the voice to OmniVoice · Balanced, or to Convai · Cloud voice without the OmniVoice pack. Without the pack, Natural speech and Expressive emotions turn off."] = "Parlez dans n’importe quelle langue ; chaque personnage répond dans la vôtre.\n\nUne copie multilingue séparée de chaque personnage est utilisée, si bien que ce qu’ils retiennent de ces échanges reste à part de vos conversations en anglais. Oublier un personnage efface les deux.\n\nPocket et Voxtral ne parlent qu’anglais : ceci fait donc passer la voix sur OmniVoice · Équilibré, ou sur Convai · Voix cloud sans le pack OmniVoice. Sans le pack, Parole naturelle et Émotions expressives sont désactivées.",
    ["Turning it on also selects Local AI, the largest uncensored model that fits and a local voice instead of a cloud one. Turning it off restores your choices."] = "L’activer sélectionne aussi Local AI, le plus grand modèle non censuré qui tienne, et une voix locale au lieu d’une voix cloud. La désactivation restaure vos choix.",
    ["Use it if companions seem to look above or below your eyes."] = "À activer si les compagnons semblent viser au-dessus ou sous vos yeux.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Cloud Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · clé Mistral requise",
    ["{name} (custom · too large)"] = "{name} (personnalisé · trop grand)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (personnalisé, {size} GB, nécessite {need} GB)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (personnalisé, {size} GB, trop grand pour cette carte)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Effacer vos souvenirs chez tous les personnages avec qui vous avez parlé.\n\nVotre identité de joueur reste. Une confirmation vient d’abord.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Enregistre un fichier de rapport à envoyer au développeur.\n\nLes clés d’API, jetons, identifiants, audio du micro et texte des conversations sont exclus. Sans le service de conversation, un rapport plus court est créé à partir des fichiers lisibles par le jeu.",
    ["The Mature pack’s uncensored models give the full effect; standard models mostly refuse sex. Pack: installed."] = "Modèles non censurés du Mature pack : effet complet. Les standards refusent surtout le sexe. Pack : installé.",
    ["The Mature pack’s uncensored models give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Modèles non censurés du Mature pack : effet complet. Les standards refusent surtout le sexe. Pack : non installé (optionnel, sur la page Hugging Face du mod).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Sans choix, Local AI charge le plus grand modèle qui tient dans votre mémoire graphique libre.\n\nUn modèle à la fois ; un changement prend effet au prochain chargement. Modèle manquant, trop gros ou défaillant : remplacé par le plus grand qui tient, avec un seul avis.",
    ["Body gestures"] = "Gestes corporels",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai n'a pas accepté votre clé d'API. Vérifiez-la dans Paramètres > Fournisseur de conversation.",
    ["Local AI could not start, so a cloud provider is used. Check Local AI in Settings > Conversation provider."] = "Local AI n'a pas pu démarrer, un fournisseur cloud est donc utilisé. Vérifiez Local AI dans Paramètres > Fournisseur de conversation.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Local AI n'a pas pu démarrer. Vérifiez Local AI dans Paramètres > Fournisseur de conversation.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral n'a pas accepté votre clé. Vérifiez-la dans Paramètres > Fournisseur de conversation.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Mistral n'a pas encore de clé, Convai est donc utilisé. Ajoutez votre clé dans Paramètres > Fournisseur de conversation.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Nécessite une clé d'API Mistral (ajoutez-la dans Paramètres > Fournisseur de conversation)",
    ["Requires an Inworld key (add it in Settings > Development)"] = "Nécessite une clé d’API Inworld (ajoutez-la dans Paramètres > Développement)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Parler aux compagnons nécessite Convai pour le moment. Définissez Fournisseur de conversation sur Convai (offre gratuite) dans Paramètres > Fournisseur de conversation, ou tapez votre message.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider."] = "La limite de conversations a été atteinte. Réessayez plus tard, ou ajoutez une clé d'API Mistral gratuite et réglez le Fournisseur de conversation sur Mistral dans Paramètres > Fournisseur de conversation.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Votre clé d'API Convai a atteint la limite de son offre. Réessayez plus tard ou ajoutez une autre clé dans Paramètres > Fournisseur de conversation.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Mistral (free, with your own free key) allows about 5,000 turns a day. Local AI is unlimited and runs on your PC."] = "Vous avez atteint la limite quotidienne de Convai (offre gratuite). Elle se réinitialise demain. Pour continuer dès maintenant, choisissez un autre fournisseur dans Paramètres > Fournisseur de conversation. Mistral (gratuit, avec votre propre clé gratuite) permet environ 5 000 tours par jour. Local AI est illimitée et fonctionne sur votre PC.",
    ["Today’s {limit} Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "{limit} tours Convai épuisés.\nEssayez Mistral (clé gratuite, ~5 000/j) ou Local AI (illimitée).",
    ["Today’s Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Tours Convai épuisés.\nEssayez Mistral (clé gratuite, ~5 000/j) ou Local AI (illimitée).",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral or Local as the conversation provider in the settings."] = "Convai répond en ce moment, donc ces modifications n’ont pas encore d’effet. Choisissez Mistral ou Local AI comme fournisseur de conversation dans les paramètres.",
    ["Edit a character’s bio, speaking style, speaking rules and memories in your browser.\n\nWorks with Mistral and Local, not Convai. Changes apply from the next reply."] = "Modifiez dans le navigateur la bio, le style et les règles de parole d’un personnage, ainsi que ses souvenirs.\n\nFonctionne avec Mistral et Local AI, pas avec Convai. Les changements valent dès la réponse suivante.",
    ["Your changes work with Mistral and Local. They do not apply to Convai."] = "Vos modifications fonctionnent avec Mistral et Local AI. Elles ne s’appliquent pas à Convai.",
    ["Choosing a cloud provider turns it off."] = "Choisir un fournisseur cloud désactive ceci.",
    ["Inworld always speaks with emotion, whatever this says."] = "Inworld parle toujours avec émotion, quel que soit ce réglage.",
    ["Inworld can voice laughs and sighs too."] = "Inworld peut aussi faire entendre rires et soupirs.",
    ["Inworld speaks English only as well."] = "Inworld ne parle aussi qu’en anglais.",
    ["Inworld: the same with your own Inworld key, and it also speaks with emotion."] = "Inworld : idem avec votre propre clé d’API Inworld, et il parle aussi avec émotion.",
    ["Paste"] = "Coller",
    ["no Omni pack"] = "sans pack OmniVoice",
    ["Add your Convai API key below to see and buy a plan."] = "Ajoutez votre clé d'API Convai ci-dessous pour voir les offres et en acheter une.",
    ["Add your Convai API key first."] = "Ajoutez d'abord votre clé d'API Convai.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Ajoutez d'abord votre clé d'API Convai : copiez-la, puis choisissez Coller sur la ligne Clé d'API Convai.",
    ["Asking Convai for the payment page…"] = "Demande de la page de paiement à Convai…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Demande à Convai quelle offre votre clé possède maintenant. Après le paiement, cela peut prendre environ 15 secondes.",
    ["Billed every month."] = "Facturé chaque mois.",
    ["Billed once a year."] = "Facturé une fois par an.",
    ["Buy"] = "Acheter",
    ["Check"] = "Vérifier",
    ["Check my plan"] = "Vérifier mon offre",
    ["Checking your plan…"] = "Vérification de votre offre…",
    ["Choose Check my plan to ask Convai."] = "Choisissez Vérifier mon offre pour interroger Convai.",
    ["Contacting Convai…"] = "Contact de Convai…",
    ["Convai could not start the payment. Try again later."] = "Convai n'a pas pu lancer le paiement. Réessayez plus tard.",
    ["Convai did not accept your API key."] = "Convai n'a pas accepté votre clé d'API.",
    ["Convai does not show a paid plan for your key yet."] = "Convai n'affiche pas encore d'offre payante pour votre clé.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "Convai n'a pas encore confirmé votre offre. Vérifiez-la dans Paramètres > Offre payante Convai.",
    ["Convai paid tier"] = "Offre payante Convai",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "La page de paiement de Convai est ouverte dans votre navigateur. Votre offre est active environ 15 secondes après le paiement.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "Le service de paiement de Convai n'a pas répondu. Réessayez dans un instant.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Offres Convai pour ce mod : plus de conversations Convai avec votre propre clé d'API Convai. Ouvre une page avec les offres et leurs prix.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Les conversations avec la clé d'API Convai choisie comme fournisseur utilisent cette offre.",
    ["Get your Convai API key"] = "Obtenir votre clé d'API Convai",
    ["Manage or cancel plan"] = "Gérer ou annuler l'offre",
    ["Free"] = "Gratuit",
    ["Gamer, monthly"] = "Gamer, mensuel",
    ["Gamer, yearly"] = "Gamer, annuel",
    ["Gamer Pro, monthly"] = "Gamer Pro, mensuel",
    ["Gamer Pro, yearly"] = "Gamer Pro, annuel",
    ["Current plan"] = "Offre actuelle",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Voici votre offre actuelle. Pour la modifier ou l'annuler, choisissez Gérer ou annuler l'offre ci-dessous.",
    ["No key added"] = "Aucune clé ajoutée",
    ["Not checked yet"] = "Pas encore vérifié",
    ["Opened in your browser."] = "Ouvert dans votre navigateur.",
    ["Opening the page in your browser…"] = "Ouverture de la page dans votre navigateur…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Ouvre la page de paiement de Convai (Stripe) dans votre navigateur. Vous payez Convai directement ; le mod ne voit jamais votre carte. Votre offre est active environ 15 secondes après le paiement, puis les conversations utilisent votre clé d'API Convai.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Ouvre convai.com dans votre navigateur. Connectez-vous ou créez un compte gratuit, copiez votre clé d'API, puis revenez et choisissez Coller ci-dessous.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Ouvre votre page de facturation Convai dans votre navigateur. Connectez-vous avec le même compte Convai pour modifier ou annuler votre offre.",
    ["Plans"] = "Offres",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Offres créées par Convai pour ce mod. Elles donnent plus de conversations à votre propre clé d'API Convai ; l'offre gratuite reste inchangée.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Prix en dollars américains. Vous pouvez annuler à tout moment sur la page de facturation de Convai.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "Le service de conversation ne tourne pas, les offres ne peuvent donc pas être affichées. Redémarrez le jeu.",
    ["This key has no paid plan. Choose a plan below."] = "Cette clé n'a pas d'offre payante. Choisissez une offre ci-dessous.",
    ["Your Convai plan"] = "Votre offre Convai",
    ["Your Convai plan is active."] = "Votre offre Convai est active.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Votre offre Convai est active. Choisissez Clé d'API Convai dans Paramètres > Fournisseur de conversation.",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Votre offre Convai est active. Les conversations utilisent maintenant votre clé d'API Convai.",
    ["Your browser could not be opened."] = "Votre navigateur n'a pas pu être ouvert.",
    ["Your plan could not be read right now. Try again in a moment."] = "Votre offre n'a pas pu être lue pour le moment. Réessayez dans un instant.",
    ["{count} Convai interactions a month."] = "{count} interactions Convai par mois.",
    ["{plan}, {price} a month"] = "{plan}, {price} par mois",
    ["{plan}, {price} a year"] = "{plan}, {price} par an",
    ["Sign in with Convai"] = "Se connecter avec Convai",
    ["Sign in"] = "Se connecter",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Ouvre la page de connexion de Convai dans votre navigateur.\n\nConnectez-vous ou créez un compte gratuit : votre clé d'API Convai est alors enregistrée sur cet ordinateur, comme avec Coller. Vous avez cinq minutes.",
    ["Opening Convai’s sign-in page in your browser…"] = "Ouverture de la page de connexion de Convai dans votre navigateur…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Connectez-vous sur la page Convai dans votre navigateur. Votre clé sera enregistrée ici une fois la procédure terminée.",
    ["Signed in. Your Convai API key is saved."] = "Connexion réussie. Votre clé d'API Convai est enregistrée.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "La connexion a pris trop de temps. Choisissez Se connecter avec Convai pour réessayer.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "La connexion n'a pas abouti. Réessayez, ou copiez votre clé depuis convai.com et choisissez Coller.",
    ["Choose one of the listed voices for V."] = "Choisissez l’une des voix proposées pour V.",
    ["Pocket · On your PC"] = "Pocket · Sur votre PC",
    ["V’s voice engine"] = "Moteur de voix de V",
    ["When you type a line, V says it out loud too, in the male or female V voice that matches yours. Push-to-talk is never replayed.\n\nV speaks first, then the companion answers. A slow V line is skipped, so the reply is never delayed. The line always shows as a subtitle.\n\nThe voice that speaks it is chosen in the next row."] = "Quand vous tapez une réplique, V la dit aussi à voix haute, avec la voix masculine ou féminine de V correspondant à la vôtre. Le push-to-talk n’est jamais rejoué.\n\nV parle d’abord, puis le compagnon répond. Une réplique lente de V est sautée, si bien que la réponse n’est jamais retardée. La réplique s’affiche toujours sous forme de sous-titre.\n\nLa voix qui la prononce se choisit dans la ligne suivante.",
    ["Pocket: runs on your processor and starts in about 0.2 s. If the companions use another voice, it loads its own small voice model just for V.\n\nVoxtral: made in the cloud with your Mistral key, so nothing loads on your PC. Starts in about a second. English only, and not with Mature content on.\n\nWhichever you pick, a line that is not ready in time is skipped."] = "Pocket : tourne sur votre processeur et démarre en 0,2 s environ. Si les compagnons utilisent une autre voix, il charge son propre petit modèle de voix, uniquement pour V.\n\nVoxtral : généré dans le cloud avec votre clé Mistral, donc rien ne se charge sur votre PC. Démarre en une seconde environ. En anglais uniquement, et pas avec le contenu pour adultes activé.\n\nQuel que soit votre choix, une réplique non prête à temps est sautée.",
    ["Johnny in your head"] = "Johnny dans votre tête",
    ["Johnny Silverhand answers when you use the talk keys with nobody in front of you, as the voice in V’s head. He knows your jobs and your story so far, and what he thinks of you follows it.\n\nOnly while the story has him in V’s head. He stays quiet during scenes, calls, dialogue choices and fights, and when the game gives him a line."] = "Johnny Silverhand vous répond quand vous utilisez les touches de conversation sans personne devant vous, comme la voix dans la tête de V. Il connaît vos missions et votre histoire jusqu’ici, et son opinion sur vous évolue en conséquence.\n\nUniquement tant que l’histoire le place dans la tête de V. Il reste silencieux pendant les scènes, les appels, les choix de dialogue et les combats, et quand le jeu lui donne une réplique.",
    ["Johnny’s standing"] = "Relation avec Johnny",
    ["Where you and Johnny stand in this save’s story. It follows what you have been through together, such as Alt, the oil fields, Rogue and the reunion concert.\n\nRead from your save; nothing is stored."] = "Où vous en êtes, Johnny et vous, dans l’histoire de cette sauvegarde. Cela suit ce que vous avez traversé ensemble, comme Alt, les champs pétrolifères, Rogue et le concert des retrouvailles.\n\nLu depuis votre sauvegarde ; rien n’est stocké.",
    ["Not in your head yet"] = "Pas encore dans votre tête",
    ["Wary"] = "Méfiant",
    ["Grudging respect"] = "Respect réticent",
    ["Friends"] = "Amis",
    ["Close friends"] = "Très proches",
    ["Gone after the ending"] = "Parti après la fin",
    ["Johnny speaks up"] = "Johnny prend la parole",
    ["Rare"] = "Rare",
    ["Normal"] = "Normal",
    ["Choose how often Johnny speaks up."] = "Fréquence des interventions de Johnny.",
    ["A pack is one folder too deep. See Help in Settings."] = "Un pack a un dossier de trop. Voir Aide dans Paramètres.",
    ["All files found."] = "Tous les fichiers trouvés.",
    ["Browser"] = "Navigateur",
    ["Found."] = "Trouvé.",
    ["Found: {list}."] = "Trouvé : {list}.",
    ["Game version"] = "Version du jeu",
    ["Graphics card"] = "Carte graphique",
    ["Internet"] = "Internet",
    ["Loaded."] = "Chargé.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "L’IA locale n’a pas pu démarrer. Générez un rapport ci-dessous et envoyez-le, ou choisissez un autre fournisseur de conversation.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "L’IA locale n’a trouvé aucune carte graphique utilisable. Elle a besoin d’une carte NVIDIA ou AMD avec un pilote à jour. Mettez le pilote à jour ou choisissez un autre fournisseur de conversation.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Manquants : {files}. Réextrayez le zip Scripts dans le dossier de Cyberpunk 2077 et laissez-le remplacer les fichiers.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. Les fichiers créés par le mod vont dans son dossier Overwrite ; laissez-les là. Mentionnez Mod Organizer 2 lorsque vous envoyez un rapport.",
    ["Mod files"] = "Fichiers du mod",
    ["Mod manager"] = "Gestionnaire de mods",
    ["Moved into place from {folder}: {packs}."] = "Déplacés depuis {folder} : {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Aucun pack d’IA locale trouvé. Téléchargez-en un depuis la page Hugging Face du mod et extrayez-le dans le dossier de Cyberpunk 2077, ou choisissez un autre fournisseur de conversation.",
    ["No problem found. Select a line to see what was checked."] = "Aucun problème trouvé. Sélectionnez une ligne pour voir ce qui a été vérifié.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the Runtime zip straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game."] = "Aucune trace du service de conversation dans cette session : le Runtime est absent ou ne s’est pas chargé. Extrayez le zip du Runtime directement dans le dossier de Cyberpunk 2077 (pas dans un nouveau dossier), vérifiez que red4ext/plugins/AiNpcCyberpunkMod est présent, puis redémarrez le jeu.",
    ["None found: installed by hand."] = "Aucun trouvé : installé à la main.",
    ["None installed. They are optional."] = "Aucun installé. Ils sont facultatifs.",
    ["Not needed: Local AI and the voice run on this PC."] = "Inutile : l’IA locale et la voix tournent sur ce PC.",
    ["Not used"] = "Non utilisé",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Ce n’est pas votre fournisseur de conversation. Choisissez-le dans Paramètres > Fournisseur de conversation.",
    ["Note"] = "Remarque",
    ["OK"] = "OK",
    ["Optional packs"] = "Packs facultatifs",
    ["Problem"] = "Problème",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Problèmes trouvés : {count}. Sélectionnez une ligne marquée Problème pour lire quoi faire.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "RED4ext n’est pas chargé. Installez-le depuis Nexus Mods, puis redémarrez le jeu. Il lance aussi le service de conversation.",
    ["Reached {host}."] = "{host} joignable.",
    ["Scripts and Runtime"] = "Scripts et Runtime",
    ["Scripts {scripts} and Runtime {runtime} do not match. Download both for the same version and extract them into the Cyberpunk 2077 folder."] = "Scripts {scripts} et Runtime {runtime} ne correspondent pas. Téléchargez les deux pour la même version et extrayez-les dans le dossier de Cyberpunk 2077.",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} et Runtime {runtime}.",
    ["Setup check"] = "Vérification de l’installation",
    ["Some mod files are missing. Extract the Scripts zip again. See Help in Settings."] = "Des fichiers du mod manquent. Réextrayez le zip Scripts. Voir Aide dans Paramètres.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Certains fichiers du pack n’ont pas pu être déplacés, car d’autres fichiers différents sont déjà là. Réextrayez le pack dans le dossier de Cyberpunk 2077 et laissez-le remplacer les fichiers.",
    ["The Runtime is incomplete ({code}). Download it again and extract it into the Cyberpunk 2077 folder, then restart the game."] = "Le Runtime est incomplet ({code}). Téléchargez-le à nouveau, extrayez-le dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["The Scripts and Runtime versions do not match. Install the same version of both."] = "Les versions de Scripts et Runtime diffèrent. Installez la même version des deux.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "Le service de conversation n’a pas accès à Internet. Voir Aide dans Paramètres.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "Le service de conversation ne peut pas joindre {host}. Autorisez Node.js dans votre pare-feu ou antivirus (Windows le demande une seule fois ; choisissez Autoriser l’accès), vérifiez votre connexion Internet, puis redémarrez le jeu.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "Le service de conversation n’a pas pu démarrer ({code}). Redémarrez le jeu. Si cela se reproduit, générez un rapport ci-dessous et envoyez-le.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "Le service de conversation n’a pas démarré. Runtime installé ? Voir Aide dans Paramètres.",
    ["The game version could not be read."] = "La version du jeu n’a pas pu être lue.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Ce PC ne peut pas résoudre {host}. Vérifiez votre connexion Internet, puis redémarrez le jeu.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Ouvrez r6/logs/redscript_rCURRENT.log. Un mod cité là empêche les scripts de charger.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware, Audioware or redscript, or a game version other than 2.31, can also cause it."] = "Les scripts de ce mod ne se sont pas chargés. Ouvrez r6/logs/redscript_rCURRENT.log. Si l’erreur nomme un autre mod, c’est lui le problème. Un Codeware, Audioware ou redscript manquant ou ancien, ou une version du jeu autre que 2.31, peut aussi en être la cause.",
    ["Missing: {names}. Install them and restart the game."] = "Manquants : {names}. Installez-les et redémarrez le jeu.",
    ["Install or update: {names}. Then restart the game."] = "Installez ou mettez à jour : {names}. Puis redémarrez le jeu.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "Codeware est trop ancien. Mettez-le à jour depuis Nexus Mods, puis redémarrez le jeu.",
    ["Version {version}."] = "Version {version}.",
    ["Version {version}. The mod is tested on 2.31 only, so some things may not work."] = "Version {version}. Le mod n’est testé que sur la 2.31 : certaines choses peuvent ne pas fonctionner.",
    ["Vortex. Install the Runtime and the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say."] = "Vortex. Installez à la main le Runtime et les packs facultatifs dans le dossier de Cyberpunk 2077, comme l’indiquent les étapes d’installation.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "{name} est manquant. Installez-le depuis Nexus Mods, puis redémarrez le jeu.",
    ["{name}, {memory} GB of video memory."] = "{name}, {memory} GB de mémoire vidéo.",
    ["{packs} is one folder too deep, in {folder}. Move the red4ext folder inside it into the Cyberpunk 2077 folder, then restart the game."] = "{packs} contient un dossier de trop, dans {folder}. Déplacez le dossier red4ext qui s’y trouve dans le dossier de Cyberpunk 2077, puis redémarrez le jeu.",
    ["Add an endpoint URL and a model ID first."] = "Ajoutez d’abord l’URL d’endpoint et l’ID du modèle.",
    ["Convai: the custom provider is not set up yet"] = "Convai : fournisseur personnalisé non configuré",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Copiez l’URL de base de votre fournisseur, par exemple https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 ou http://localhost:11434/v1 (Ollama). Elle est lue une seule fois depuis le presse-papiers et enregistrée uniquement sur cet ordinateur.\n\nSeuls cet ordinateur et votre réseau domestique peuvent utiliser http://. Vous pouvez aussi renseigner endpoint=, model= et api-key= dans player-custom-endpoint.txt, dans le dossier du service de conversation.\n\nRien n’est envoyé tant que vous ne choisissez pas ce fournisseur ou n’appuyez pas sur Tester la connexion.",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Copiez d’abord l’ID du modèle de votre fournisseur, par exemple meta-llama/llama-3.1-8b-instruct sur OpenRouter ou llama3.2 sur Ollama. Il est lu une seule fois depuis le presse-papiers et enregistré uniquement sur cet ordinateur.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Copiez d’abord votre clé d’API auprès de votre fournisseur. Elle est lue une seule fois depuis le presse-papiers et enregistrée uniquement sur cet ordinateur. Un serveur installé sur votre propre ordinateur, comme Ollama ou LM Studio, n’a généralement pas besoin de clé.",
    ["Custom (OpenAI-compatible)"] = "Personnalisé (API OpenAI)",
    ["Custom API key"] = "Clé d’API propre",
    ["Custom endpoint URL"] = "URL d’endpoint propre",
    ["Custom model ID"] = "ID de modèle propre",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Réponses du fournisseur personnalisé : voix locale, pas la voix cloud de Convai.",
    ["Custom: key not accepted"] = "Personnalisé : clé non acceptée",
    ["Custom: model unavailable"] = "Personnalisé : modèle indisponible",
    ["Custom: out of credits"] = "Personnalisé : crédits épuisés",
    ["Custom: rate limited for now"] = "Personnalisé : limité pour l’instant",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Supprime l’URL d’endpoint enregistrée. Le fournisseur personnalisé en a besoin pour répondre.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Supprime la clé enregistrée. Les réponses du fournisseur personnalisé sont ensuite demandées sans clé.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Supprime l’ID de modèle enregistré. Le fournisseur personnalisé en a besoin pour répondre.",
    ["Failed"] = "Échec",
    ["It answered in {ms} ms."] = "Réponse en {ms} ms.",
    ["It could not be saved."] = "Impossible de l’enregistrer.",
    ["Model ID: {model}"] = "ID de modèle : {model}",
    ["Only https:// works outside this computer and your home network."] = "Seul https:// fonctionne hors de cet ordinateur et de votre réseau domestique.",
    ["Paste API key"] = "Coller la clé d’API",
    ["Paste endpoint URL"] = "Coller l’URL",
    ["Paste model ID"] = "Coller l’ID du modèle",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Envoie un message minuscule à votre endpoint avec l’ID de modèle et la clé enregistrés, et affiche sa réponse. Cela consomme presque rien de vos crédits.",
    ["Test"] = "Tester",
    ["Test connection"] = "Tester la connexion",
    ["Testing the connection…"] = "Test de la connexion…",
    ["Testing…"] = "Test en cours…",
    ["That is too long."] = "C’est trop long.",
    ["That was not accepted."] = "Ce n’a pas été accepté.",
    ["The account is out of credits. Add credits with your provider."] = "Le compte n’a plus de crédits. Ajoutez-en auprès de votre fournisseur.",
    ["The address must start with https:// or http://."] = "L’adresse doit commencer par https:// ou http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "L’adresse vous redirige ailleurs. Utilisez l’adresse finale fournie par votre fournisseur.",
    ["The clipboard does not hold a model ID."] = "Le presse-papiers ne contient pas d’ID de modèle.",
    ["The clipboard does not hold a web address."] = "Le presse-papiers ne contient pas d’adresse web.",
    ["The clipboard does not hold an API key."] = "Le presse-papiers ne contient pas de clé d’API.",
    ["The clipboard is empty. Copy it first."] = "Le presse-papiers est vide. Copiez d’abord.",
    ["The connection test failed."] = "Le test de connexion a échoué.",
    ["The connection works. The endpoint accepted your model and key."] = "La connexion fonctionne. L’endpoint a accepté votre modèle et votre clé.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "Le service de conversation ne tourne pas, rien ne peut donc être testé. Redémarrez le jeu.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Personnalisé : clé refusée. Vérifiez-la dans Paramètres > Fournisseur de conversation.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Le fournisseur personnalisé n’a pas répondu. Vérifiez l’adresse dans Paramètres ou réessayez.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Fournisseur personnalisé : ID de modèle inconnu. Vérifiez dans Paramètres.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Pas de fournisseur personnalisé : Convai utilisé. Ajoutez URL et ID du modèle dans Paramètres.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "Le fournisseur personnalisé limite les requêtes. Réessayez dans un instant.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Plus de crédits chez le fournisseur personnalisé. Ajoutez-en, puis réessayez.",
    ["The endpoint URL was removed."] = "L’URL d’endpoint a été supprimée.",
    ["The endpoint answered with no text. Check the model ID."] = "L’endpoint a répondu sans texte. Vérifiez l’ID du modèle.",
    ["The endpoint did not accept your API key."] = "L’endpoint n’a pas accepté votre clé d’API.",
    ["The endpoint did not answer. Check its address."] = "L’endpoint n’a pas répondu. Vérifiez son adresse.",
    ["The endpoint does not know that model ID."] = "L’endpoint ne connaît pas cet ID de modèle.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "L’endpoint vous limite pour l’instant. Réessayez dans un instant.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "L’endpoint vous limite. Attendez environ {seconds} secondes, puis réessayez.",
    ["The endpoint refused the request. Check the model ID and the address."] = "L’endpoint a refusé la requête. Vérifiez l’ID du modèle et l’adresse.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "L’endpoint signale une erreur de son côté. Réessayez dans un instant.",
    ["The endpoint took too long to answer."] = "L’endpoint a mis trop de temps à répondre.",
    ["The model ID was removed."] = "L’ID du modèle a été supprimé.",
    ["The provider said: {detail}"] = "Le fournisseur a dit : {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Cette adresse n’est pas chiffrée, ce qui est acceptable sur votre ordinateur ou votre réseau domestique.",
    ["Use the base URL only: no password, query or #."] = "Indiquez seulement l’URL de base, sans mot de passe, requête ni #.",
    ["Waiting for the endpoint to answer…"] = "En attente de la réponse de l’endpoint…",
    ["Custom: free daily limit reached"] = "Personnalisé : limite quotidienne gratuite atteinte",
    ["New address saved. Paste your API key again for it."] = "Nouvelle adresse enregistrée. Collez à nouveau votre clé d’API.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Limite quotidienne gratuite atteinte pour ce modèle. Réinitialisation à {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Limite quotidienne gratuite atteinte pour ce modèle. Réessayez après la réinitialisation.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Ce modèle réfléchit sans répondre. Choisissez un modèle sans raisonnement dans Paramètres.",
    ["A change takes effect after the current reply. No game restart is needed."] = "Un changement prend effet après la réponse en cours. Aucun redémarrage du jeu n’est nécessaire.",
    ["All"] = "Tous",
    ["Also changed: {names}."] = "Également modifié : {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Choisissez un personnage de la liste ci-dessous. Il n'a pas besoin d'être dans votre groupe actuel.",
    ["Defaults restored."] = "Valeurs par défaut rétablies.",
    ["Drag the slider, or press left and right, to turn the page."] = "Faites glisser le curseur ou appuyez sur les flèches gauche et droite pour changer de page.",
    ["How loud the mod’s voices are, for companions, characters and V’s typed lines. 100 is the normal level.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. The game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Le volume des voix du mod, pour les compagnons, les personnages et les phrases que V tape. 100 est le niveau normal.\n\nAu-dessus de 100, les voix sont plus fortes, avec un limiteur pour éviter les craquements. Les dialogues et les sons du jeu ne changent pas.\n\nLa prochaine réponse l’utilise.",
    ["Native Settings UI is too old. Install version 1.96 from Nexus Mods, then restart the game."] = "Native Settings UI est obsolète. Installez la version 1.96 depuis Nexus Mods, puis redémarrez le jeu.",
    ["Not available right now."] = "Non disponible pour le moment.",
    ["Open Settings to restore its defaults."] = "Ouvrez Paramètres pour rétablir ses valeurs par défaut.",
    ["Page"] = "Page",
    ["Show only the models whose name starts with this letter."] = "N’affiche que les modèles dont le nom commence par cette lettre.",
    ["Starts with"] = "Commence par",
    ["The Companion Manager needs Native Settings UI (Nexus Mods)"] = "La gestion des compagnons nécessite Native Settings UI (Nexus Mods)",
    ["The settings could not be saved. Nothing was changed."] = "Les paramètres n'ont pas pu être enregistrés. Rien n'a été modifié.",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Mistral (with your free key, about 5,000 turns a day) or Local AI (unlimited)."] = "Vous avez utilisé vos {limit} tours du jour. Ils reviennent demain. Pour continuer dès maintenant, choisissez Mistral (avec votre clé gratuite, environ 5 000 tours par jour) ou Local AI (aucune limite).",
    ["Johnny says something on his own after you meet someone he knows of, finish a job, or a romance moves on. Needs Johnny in your head.\n\nRare: at most twice an hour. Normal: at most six times an hour, never closer than five minutes.\n\nOn the Convai free tier each remark uses one of the day’s turns; remarks never take more than a tenth of them."] = "Johnny prend la parole de lui-même après que vous avez rencontré quelqu’un dont il a entendu parler, terminé une mission ou qu’une romance avance. Nécessite Johnny dans votre tête.\n\nRare : au plus deux fois par heure. Normal : au plus six fois par heure, jamais à moins de cinq minutes d’intervalle.\n\nSur l’offre gratuite de Convai, chaque remarque utilise l’un des tours du jour ; les remarques ne prennent jamais plus d’un dixième de ceux-ci.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral or Local AI, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Qui rédige les réponses de vos compagnons. Un changement attend qu’aucune conversation ne soit en cours.\n\nL’offre gratuite de Convai ne demande aucune configuration et donne de meilleures réponses. L’option Clé d’API Convai utilise votre propre clé, et Mistral utilise son offre gratuite avec votre propre clé gratuite ; la mémoire reste sur cet ordinateur.\n\nAvec Mistral ou Local AI, la voix cloud de Convai est remplacée par une voix locale. La parole est reconnue sur cet ordinateur, donc la clé vocale fonctionne.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral or Local AI, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Qui rédige les réponses de vos compagnons. Un changement attend qu’aucune conversation ne soit en cours.\n\nL’offre gratuite de Convai ne demande aucune configuration et donne de meilleures réponses. L’option Clé d’API Convai utilise votre propre clé, et Mistral utilise son offre gratuite avec votre propre clé gratuite ; la mémoire reste sur cet ordinateur.\n\nAvec Mistral ou Local AI, la voix cloud de Convai est remplacée par une voix locale. La reconnaissance vocale pour la clé vocale n’est pas encore disponible avec eux, donc tapez vos messages.",
}
